public static JsonbSerializer<?>[] joinJsonbSerializerArrays(final JsonbSerializer<?>[]... serializerArrays) {
        final List<JsonbSerializer<?>> all = joinArrays(serializerArrays);
        return all.toArray(new JsonbSerializer<?>[all.size()]);
    }
